def transform(g):
    h,w=len(g),len(g[0])
    seeds=[r for row in g if (r:=runs_of(row))]
    out=[r[:] for r in g]
    for i,row in enumerate(g):
        if row[0]!=0: continue
        for j,v in enumerate(row):
            if v==0: continue
            run=next(s for s in seeds if v in s)
            start=j-run.index(v)
            for k,c in enumerate(run):
